// generated by tools/build_verse_manifests.js from pgp_english.js — Dual-view English for the chapters of pgp_verses/pgp_intro.js
registerEnglish([["PGP-Introduction",1,1,"The Pearl of Great Price is a selection of choice materials touching many significant aspects of the faith and doctrine of The Church of Jesus Christ of Latter-day Saints."],["PGP-Introduction",1,2,"These items were translated and produced by the Prophet Joseph Smith, and most were published in the Church periodicals of his day."],["PGP-Introduction",1,3,"The first collection of materials carrying the title Pearl of Great Price was made in 1851 by Elder Franklin D. Richards, then a member of the Council of the Twelve and president of the British Mission."],["PGP-Introduction",1,4,"Its purpose was to make more readily accessible some important articles that had had limited circulation in the time of Joseph Smith."],["PGP-Introduction",1,5,"As Church membership increased throughout Europe and America, there was a need to make these items available."],["PGP-Introduction",1,6,"The Pearl of Great Price received wide use and subsequently became a standard work of the Church by action of the First Presidency and the general conference in Salt Lake City on October 10, 1880."],["PGP-Introduction",1,7,"Several revisions have been made in the contents as the needs of the Church have required."],["PGP-Introduction",1,8,"In 1878 portions of the book of Moses not contained in the first edition were added."],["PGP-Introduction",1,9,"In 1902 certain parts of the Pearl of Great Price that duplicated material also published in the Doctrine and Covenants were omitted."],["PGP-Introduction",1,10,"Arrangement into chapters and verses, with footnotes, was done in 1902."],["PGP-Introduction",1,11,"The first publication in double-column pages, with index, was in 1921."],["PGP-Introduction",1,12,"No other changes were made until April 1976, when two items of revelation were added."],["PGP-Introduction",1,13,"In 1979 these two items were removed from the Pearl of Great Price and placed in the Doctrine and Covenants, where they now appear as sections 137 and 138."],["PGP-Introduction",1,14,"In the present edition some changes have been made to bring the text into conformity with earlier documents."],["PGP-Introduction",1,15,"Following is a brief introduction to the present contents:"],["PGP-Introduction",1,16,"Selections from the Book of Moses. An extract from the book of Genesis of Joseph Smith’s translation of the Bible, which he began in June 1830."],["PGP-Introduction",1,17,"The Book of Abraham. An inspired translation of the writings of Abraham. Joseph Smith began the translation in 1835 after obtaining some Egyptian papyri. The translation was published serially in the Times and Seasons beginning March 1, 1842, at Nauvoo, Illinois."],["PGP-Introduction",1,18,"Joseph Smith—Matthew. An extract from the testimony of Matthew in Joseph Smith’s translation of the Bible (see Doctrine and Covenants 45:60–61 for the divine injunction to begin the translation of the New Testament)."],["PGP-Introduction",1,19,"Joseph Smith—History. Excerpts from Joseph Smith’s official testimony and history, which he and his scribes prepared in 1838–39 and which was published serially in the Times and Seasons in Nauvoo, Illinois, beginning on March 15, 1842."],["PGP-Introduction",1,20,"The Articles of Faith of The Church of Jesus Christ of Latter-day Saints. A statement by Joseph Smith published in the Times and Seasons March 1, 1842, in company with a short history of the Church that was popularly known as the Wentworth Letter."]]);
